"""Haircuts on the head, generated by code: guide strands plus interpolated children.

The method from the particle-hair tutorial (notes/tutorial-hair-particles.md), done on
Blender's current Curves hair and fully scripted:

  1. Scalp map. Every point on the head gets a density (0 to 1: where hair grows and how
     thick), a length and a combing direction, all from smooth functions of position
     relative to the eyes and ears. This replaces weight painting and hand combing.
  2. Guides. A few hundred guide strands are grown from the scalp. Each step moves along
     the combing direction, then is pulled back onto a shell just above the scalp whose
     height grows along the strand, so hair lies on the head with some volume instead of
     sticking out.
  3. Children. Tens of thousands of child strands are rooted by density. Each copies the
     shape of its nearest guides (weighted), then is clumped toward its main guide near
     the tip and given frizz.
  4. Colour. Each strand gets a melanin value (dark vs grey) from the scalp map, so the
     sides can be greyer than the top, and the shader reads it per strand.
"""
import bpy
import numpy as np
from mathutils import Vector
from mathutils.bvhtree import BVHTree

from . import accessories, garments, human


def _sigmoid(x, width):
    return 1.0 / (1.0 + np.exp(-x / width))


class Scalp:
    """The head surface of a morphed body, with landmarks and fast nearest-point queries."""

    def __init__(self, base_verts):
        c = garments._body_coordinates()
        self.lm = accessories.face_landmarks(base_verts)
        self.verts = human.to_blender(base_verts)
        head = (np.arange(len(self.verts)) < human.BODY_VERTS) & (c["part"] == "neck")
        self.faces = [f for f in human.base_mesh()[2] if all(head[v] for v in f)]
        self.bvh = BVHTree.FromPolygons([Vector(v) for v in self.verts], self.faces)
        self.eye_z = self.lm["eye_z"]
        self.centre = np.array([0.0, (self.lm["front_y"] + self.lm["back_y"]) / 2.0, self.eye_z + 0.02])

    def nearest(self, points):
        out_p, out_n = np.empty_like(points), np.empty_like(points)
        for i, p in enumerate(points):
            q, n, _, _ = self.bvh.find_nearest(Vector(p))
            out_p[i], out_n[i] = q, n
        # make normals point away from the head's centre
        flip = np.einsum("ij,ij->i", out_n, out_p - self.centre) < 0
        out_n[flip] *= -1
        return out_p, out_n


def short_back_and_sides(scalp, points, top_length=0.065, side_length=0.006, back_length=0.008,
                         hairline=0.058, nape=-0.06, grey_top=0.55, grey_sides=0.8):
    """Scalp map for a short, combed-back cut: longer on top, clipped short at the sides and
    back. Returns density, length, combing direction and greyness per point."""
    rel = points - scalp.centre
    h = points[:, 2] - scalp.eye_z                          # height above the eyes
    back = points[:, 1] - scalp.lm["front_y"]               # 0 at the nose tip, about 0.2 at the back
    x = np.abs(points[:, 0])
    # Where hair grows: above a hairline that is high on the forehead, at the temples and
    # sideburns lower, and at the back down to the nape; never round the ears.
    # (First version measured depth with the wrong sign and grew hair over the face.)
    forehead_line = hairline - 0.03 * np.clip(x / 0.07, 0.0, 1.0)
    w_face = _sigmoid(0.085 - back, 0.008)                  # 1 on the front of the head
    w_side = _sigmoid(0.14 - back, 0.008) * (1.0 - w_face)  # temples and sideburns
    line = w_face * forehead_line + w_side * (-0.02) + (1.0 - w_face - w_side) * nape
    ears = np.hypot(points[:, 1] - (scalp.lm["front_y"] + 0.105), points[:, 2] - (scalp.eye_z - 0.03))
    density = _sigmoid(h - line, 0.004) * np.where(x > 0.055, _sigmoid(ears - 0.040, 0.004), 1.0)
    # Length: long on top, short sides and back, blended over a few centimetres.
    top = _sigmoid(h - 0.065, 0.012) * _sigmoid(0.075 - x, 0.01)
    length = side_length + (top_length - side_length) * top
    length = np.where(rel[:, 1] > 0.02, np.minimum(length, back_length + (top_length - back_length) * top * 0.6), length)
    # Combed back and slightly up off the forehead; sides combed back and down.
    comb = np.stack([np.sign(points[:, 0]) * 0.15 * (1 - top), np.ones(len(points)), 0.25 * top - 0.6 * (1 - top)], axis=1)
    comb /= np.linalg.norm(comb, axis=1, keepdims=True)
    grey = grey_top + (grey_sides - grey_top) * (1.0 - top)  # sides greyer than the top
    return density, length, comb, grey


def curly_mop(scalp, points, length=0.11, side=0.45, fringe_cut=0.25, crown=(0.0, 0.13, 0.115),
              sweep=0.0, sweep_side=-1.0):
    """Scalp map for a full head of curls: hair everywhere above a low hairline, falling
    outward and down from the crown like a mop, with a fringe over the forehead.
    `crown` is the parting centre relative to (centre x, front of face, eye height)."""
    h = points[:, 2] - scalp.eye_z
    back = points[:, 1] - scalp.lm["front_y"]
    x = np.abs(points[:, 0])
    forehead_line = 0.042 - 0.02 * np.clip(x / 0.07, 0.0, 1.0)   # low, so the fringe covers the forehead
    w_face = _sigmoid(0.085 - back, 0.008)
    w_side = _sigmoid(0.14 - back, 0.008) * (1.0 - w_face)
    line = w_face * forehead_line + w_side * (-0.01) + (1.0 - w_face - w_side) * (-0.065)
    ears = np.hypot(points[:, 1] - (scalp.lm["front_y"] + 0.105), points[:, 2] - (scalp.eye_z - 0.03))
    density = _sigmoid(h - line, 0.004) * np.where(x > 0.055, _sigmoid(ears - 0.035, 0.004), 1.0)
    # long on top, shorter low on the sides and back so the mop ends about the top of the
    # ears (step 2 hung to the jaw)
    length = np.full(len(points), length) * (side + (1.0 - side) * _sigmoid(h - 0.05, 0.012))
    # the fringe stops at the brows (step 3 hung over one eye)
    length *= 1.0 - fringe_cut * w_face * _sigmoid(0.10 - h, 0.01)
    # a longer lock falling over one eye (sweep_side -1: the character's right, x < 0)
    over = w_face * _sigmoid(sweep_side * points[:, 0] - 0.005, 0.012) * _sigmoid(0.11 - h, 0.012)
    length *= 1.0 + sweep * over
    c = np.array([crown[0], scalp.lm["front_y"] + crown[1], scalp.eye_z + crown[2]])
    comb = points - c
    comb[:, 2] = np.minimum(comb[:, 2], 0.0) - 0.02          # out from the crown and down
    comb /= np.maximum(np.linalg.norm(comb, axis=1, keepdims=True), 1e-9)
    return density, length, comb, np.zeros(len(points))


def sample_roots(scalp, count, style, seed=0, oversample=4):
    """Root points on the scalp, distributed by the style's density."""
    rng = np.random.default_rng(seed)
    from . import hair as hair_mod
    pts, nrm = hair_mod.sample_surface(scalp.verts, scalp.faces, count * oversample, seed=seed)
    density = style(scalp, pts)[0]
    keep = rng.random(len(pts)) < density
    pts, nrm = pts[keep][:count], nrm[keep][:count]
    flip = np.einsum("ij,ij->i", nrm, pts - scalp.centre) < 0
    nrm[flip] *= -1
    return pts, nrm


def grow_guides(scalp, roots, style, steps=10, lift=(0.0015, 0.007), volume=0.010, wave=0.006,
                wavelength=0.035, seed=0):
    """Guide strands that follow the combing direction over the scalp, lying on a shell that
    rises from `lift[0]` above the scalp at the root to `lift[1]` at the tip."""
    _, length, _, _ = style(scalp, roots)
    pts = np.zeros((len(roots), steps, 3))
    pts[:, 0] = roots
    seg = length / (steps - 1)
    cur = roots.copy()
    phase = np.random.default_rng(seed).uniform(0.0, 2 * np.pi, len(roots))
    for k in range(1, steps):
        _, _, comb, _ = style(scalp, cur)
        on, n = scalp.nearest(cur)
        d = comb - n * np.einsum("ij,ij->i", comb, n)[:, None]           # along the surface
        d /= np.maximum(np.linalg.norm(d, axis=1, keepdims=True), 1e-9)
        # sideways wave along longer strands, so the top breaks up into locks
        side = np.cross(n, d)
        travelled = seg * k
        sway = wave * np.clip((length - 0.02) / 0.05, 0.0, 1.0) * np.cos(2 * np.pi * travelled / wavelength + phase)
        d = d + side * (sway / np.maximum(seg, 1e-6))[:, None] * 0.25
        d /= np.maximum(np.linalg.norm(d, axis=1, keepdims=True), 1e-9)
        nxt = cur + d * seg[:, None]
        q, qn = scalp.nearest(nxt)
        t = k / (steps - 1)
        # longer strands stand further off the scalp (a quiff of volume on top); the short
        # sides stay close. (A flat shell made the hair look painted on.)
        extra = volume * np.clip((length - 0.02) / 0.05, 0.0, 1.0) * np.sin(np.pi * min(t * 1.2, 1.0))
        # short strands lie close to the skin (clipped sides); long ones rise to lift[1]
        rise = (lift[1] - lift[0]) * np.clip(length / 0.05, 0.15, 1.0)
        cur = q + qn * (lift[0] + rise * t + extra)[:, None]
        pts[:, k] = cur
    return pts


def interpolate(scalp, guides, child_roots, k=4, clump=0.45, frizz=0.0012, seed=0):
    """Children copying the shape of nearby guides, clumped toward the nearest guide's tip
    and frizzed. Kept outside the scalp."""
    rng = np.random.default_rng(seed)
    g_roots = guides[:, 0]
    shapes = guides - g_roots[:, None, :]
    steps = guides.shape[1]
    out = np.zeros((len(child_roots), steps, 3))
    t = np.linspace(0.0, 1.0, steps)[None, :, None]
    for lo in range(0, len(child_roots), 4096):
        r = child_roots[lo:lo + 4096]
        d = np.linalg.norm(r[:, None, :] - g_roots[None, :, :], axis=2)
        idx = np.argsort(d, axis=1)[:, :k]
        dk = np.take_along_axis(d, idx, axis=1)
        w = 1.0 / np.maximum(dk, 1e-4) ** 2
        w /= w.sum(axis=1, keepdims=True)
        shape = (shapes[idx] * w[:, :, None, None]).sum(axis=1)
        strand = r[:, None, :] + shape
        own = guides[idx[:, 0]]
        strand = strand + (own - strand) * (clump * t ** 1.5)          # clump toward the tip
        strand = strand + rng.normal(size=strand.shape) * frizz * t     # frizz grows along the strand
        out[lo:lo + 4096] = strand
    # nothing below the scalp
    flat = out.reshape(-1, 3)
    q, n = scalp.nearest(flat)
    depth = np.einsum("ij,ij->i", flat - q, n)
    under = depth < 0.0008
    flat[under] = q[under] + n[under] * 0.0008
    return flat.reshape(out.shape)


def material(name="Hair", melanin=0.9, white=0.02, redness=0.12, roughness=0.32, grey_attribute="grey"):
    """Principled Hair shader in melanin mode: real hair colour from pigment amounts. Per
    strand greyness lowers the melanin (white hairs mixed in), read from a curve attribute."""
    mat = bpy.data.materials.new(name)
    if mat.node_tree is None:
        mat.use_nodes = True
    nodes, links = mat.node_tree.nodes, mat.node_tree.links
    out = next(n for n in nodes if n.type == "OUTPUT_MATERIAL")
    for n in list(nodes):
        if n.type == "BSDF_PRINCIPLED":
            nodes.remove(n)
    hair = nodes.new("ShaderNodeBsdfHairPrincipled")
    hair.parametrization = "MELANIN"
    hair.inputs["Melanin Redness"].default_value = redness
    hair.inputs["Roughness"].default_value = roughness
    hair.inputs["Radial Roughness"].default_value = 0.4
    hair.inputs["Random Roughness"].default_value = 0.3
    attr = nodes.new("ShaderNodeAttribute"); attr.attribute_name = grey_attribute
    info = nodes.new("ShaderNodeHairInfo")
    # a strand is white if its random value falls below its greyness, else pigmented
    pigmented = nodes.new("ShaderNodeMath"); pigmented.operation = "GREATER_THAN"
    links.new(info.outputs["Random"], pigmented.inputs[0]); links.new(attr.outputs["Fac"], pigmented.inputs[1])
    mel = nodes.new("ShaderNodeMath"); mel.operation = "MULTIPLY_ADD"
    links.new(pigmented.outputs[0], mel.inputs[0]); mel.inputs[1].default_value = melanin - white; mel.inputs[2].default_value = white
    # (melanin 0.6 for dark and 0.12 for white came out ginger-blond: dark hair needs about
    # 0.9, white about 0.02)
    links.new(mel.outputs[0], hair.inputs["Melanin"])
    links.new(hair.outputs["BSDF"], out.inputs["Surface"])
    return mat


def build(scene, name, strands, grey, mat, radius=0.00005, parent=None):
    """A Curves hair object from strand points (n, steps, 3) and per-strand greyness."""
    n, steps, _ = strands.shape
    curves = bpy.data.hair_curves.new(name)
    curves.add_curves([steps] * n)
    curves.points.foreach_set("position", strands.astype(np.float32).ravel())
    taper = np.tile(np.linspace(radius, radius * 0.45, steps), n).astype(np.float32)
    curves.points.foreach_set("radius", taper)
    attr = curves.attributes.new("grey", "FLOAT", "CURVE")
    attr.data.foreach_set("value", np.asarray(grey, dtype=np.float32))
    curves.materials.append(mat)
    obj = bpy.data.objects.new(name, curves)
    scene.collection.objects.link(obj)
    if parent is not None:
        obj.parent = parent
        obj.matrix_parent_inverse = parent.matrix_world.inverted()
    return obj


def haircut(scene, base_verts, style=short_back_and_sides, guides=400, children=60000, steps=12,
            clump=0.55, frizz=0.0016, radius=0.00006, mat=None, parent=None, seed=0):
    """Everything above in one call. Returns (object, timings)."""
    import time
    started = time.time()
    scalp = Scalp(base_verts)
    g_roots, _ = sample_roots(scalp, guides, style, seed=seed)
    g = grow_guides(scalp, g_roots, style, steps=steps, seed=seed)
    t_guides = time.time() - started
    c_roots, _ = sample_roots(scalp, children, style, seed=seed + 1)
    kids = interpolate(scalp, g, c_roots, clump=clump, frizz=frizz, seed=seed + 2)
    grey = style(scalp, c_roots)[3]
    obj = build(scene, "Haircut", kids, grey, mat or material(), radius=radius, parent=parent)
    return obj, {"guides": len(g), "children": len(kids), "guide_seconds": round(t_guides, 1),
                 "total_seconds": round(time.time() - started, 1)}


def grow_ringlets(scalp, roots, style, steps=48, volume=0.028, rise=0.35, coil_radius=0.007,
                  coil_pitch=0.022, coil_start=0.12, droop=0.5, seed=0, return_frame=False):
    """Guide strands for curly hair, after Blender's bundled "Curl Hair Curves" node group
    (Curl Start, Radius, Frequency, Random Offset per curve): each guide is the axis of one
    ringlet that leaves the scalp, stands off it by up to `volume` metres, then coils round
    that path with radius `coil_radius`, one turn per `coil_pitch` of length. Children that
    copy one guide (see `interpolate_ringlets`) curl together, so each guide reads as a lock."""
    rng = np.random.default_rng(seed)
    _, length, _, _ = style(scalp, roots)
    n = len(roots)
    on, nrm = scalp.nearest(roots)
    axis = np.zeros((n, steps, 3))
    axis[:, 0] = roots
    cur = roots.copy()
    seg = length / (steps - 1)
    for k in range(1, steps):
        t = k / (steps - 1)
        _, _, comb, _ = style(scalp, cur)
        q, qn = scalp.nearest(cur)
        d = comb - qn * np.einsum("ij,ij->i", comb, qn)[:, None] * (1.0 - rise * (1 - t))
        d += qn * rise * (1 - t) ** 2                            # leave the scalp steeply at first
        d[:, 2] -= droop * t ** 2                                # gravity on the ends
        d /= np.maximum(np.linalg.norm(d, axis=1, keepdims=True), 1e-9)
        nxt = cur + d * seg[:, None]
        q, qn = scalp.nearest(nxt)
        height = np.einsum("ij,ij->i", nxt - q, qn)
        floor = volume * np.sin(np.pi * np.clip(t * 1.6, 0.0, 1.0) / 2) * (0.7 + 0.3 * rng.random(n) if k == 1 else 1.0)
        lift = np.maximum(floor - height, 0.0)
        cur = nxt + qn * lift[:, None]
        axis[:, k] = cur
    # coil round the axis: a frame that follows the path without twisting
    tang = np.gradient(axis, axis=1)
    tang /= np.maximum(np.linalg.norm(tang, axis=2, keepdims=True), 1e-9)
    u = np.cross(tang[:, 0], nrm)
    u /= np.maximum(np.linalg.norm(u, axis=1, keepdims=True), 1e-9)
    us = np.zeros_like(axis)
    for k in range(steps):
        u = u - tang[:, k] * np.einsum("ij,ij->i", u, tang[:, k])[:, None]
        u /= np.maximum(np.linalg.norm(u, axis=1, keepdims=True), 1e-9)
        us[:, k] = u
    vs = np.cross(tang, us)
    s_along = np.linspace(0.0, 1.0, steps)[None, :] * length[:, None]
    phase = rng.uniform(0, 2 * np.pi, n)[:, None]
    hand = rng.choice([-1.0, 1.0], n)[:, None]
    pitch = coil_pitch * rng.uniform(0.8, 1.25, n)[:, None]
    ang = hand * 2 * np.pi * s_along / pitch + phase
    t = np.linspace(0.0, 1.0, steps)[None, :]
    ramp = np.clip((t - coil_start) / 0.15, 0.0, 1.0) * rng.uniform(0.8, 1.2, n)[:, None]
    r = coil_radius * ramp
    radial = np.cos(ang)[..., None] * us + np.sin(ang)[..., None] * vs
    pts = axis + r[..., None] * radial
    if return_frame:
        # The two directions a flat ribbon lock spans: thickness outward from the axis, and
        # width across the coiling strand (the axis direction minus its part along the
        # strand; the plain axis direction mostly runs along the strand and gave thin
        # noodles in step 11).
        ct = np.gradient(pts, axis=1)
        ct /= np.maximum(np.linalg.norm(ct, axis=2, keepdims=True), 1e-9)
        across = tang - ct * np.einsum("ijk,ijk->ij", tang, ct)[..., None]
        bad = np.linalg.norm(across, axis=2) < 0.2         # near the straight root
        across[bad] = np.cross(ct, radial)[bad]
        across /= np.maximum(np.linalg.norm(across, axis=2, keepdims=True), 1e-9)
        return pts, across, radial
    return pts


def interpolate_ringlets(scalp, guides, child_roots, spread=0.0035, tip_spread=0.006, frizz=0.0006,
                         escape=0.015, seed=0):
    """Children for curly hair: each copies only its nearest guide (blending several coiled
    guides would cancel the coils out). The child's root offset is squeezed into a lock
    `spread` wide along the strand, opening to `tip_spread` at the tip. A fraction `escape`
    of strands get extra frizz, the flyaways seen round real curls."""
    rng = np.random.default_rng(seed)
    g_roots = guides[:, 0]
    steps = guides.shape[1]
    t = np.linspace(0.0, 1.0, steps)[None, :, None]
    out = np.zeros((len(child_roots), steps, 3))
    for lo in range(0, len(child_roots), 4096):
        r = child_roots[lo:lo + 4096]
        d = np.linalg.norm(r[:, None, :] - g_roots[None, :, :], axis=2)
        own = np.argmin(d, axis=1)
        g = guides[own]
        off = r - g_roots[own]
        dist = np.maximum(np.linalg.norm(off, axis=1, keepdims=True), 1e-9)
        dirn = off / dist
        rand = rng.normal(size=(len(r), 3)); rand /= np.linalg.norm(rand, axis=1, keepdims=True)
        width = spread + (tip_spread - spread) * t ** 2
        mag = np.sqrt(rng.random((len(r), 1)))[:, None, :]            # fill the lock evenly
        lock = (dirn * 0.5 + rand * 0.5)[:, None, :] * width * mag
        root_blend = np.clip(1.0 - t / 0.1, 0.0, 1.0)                  # start at the real root
        strand = g + off[:, None, :] * root_blend + lock * (1.0 - root_blend)
        fz = frizz * (1.0 + 2.0 * (rng.random((len(r), 1, 1)) < escape))   # 7x drew zig-zags
        strand = strand + np.cumsum(rng.normal(size=strand.shape), axis=1) * fz * t / np.sqrt(steps)
        out[lo:lo + 4096] = strand
    flat = out.reshape(-1, 3)
    q, n = scalp.nearest(flat)
    depth = np.einsum("ij,ij->i", flat - q, n)
    under = depth < 0.0008
    flat[under] = q[under] + n[under] * 0.0008
    return flat.reshape(out.shape)


def interpolate_ribbons(scalp, guides, across, radial, child_roots, width=0.012, thickness=0.0015,
                        taper=0.5, frizz=0.0005, escape=0.015, width_jitter=0.3, fray=0.0, shorten=0.0,
                        seed=0):
    """Children for wide, flat curls ("ribbon" locks, as in run 012's reference): each lock
    is a band `width` wide laid along its coil's axis and `thickness` deep, so when the
    guide coils the band curls like a ribbon instead of a round spring. The band narrows
    to (1 - taper) of its width at the tip."""
    rng = np.random.default_rng(seed)
    g_roots = guides[:, 0]
    steps = guides.shape[1]
    t = np.linspace(0.0, 1.0, steps)[None, :, None]
    out = np.zeros((len(child_roots), steps, 3))
    for lo in range(0, len(child_roots), 4096):
        r = child_roots[lo:lo + 4096]
        d = np.linalg.norm(r[:, None, :] - g_roots[None, :, :], axis=2)
        own = np.argmin(d, axis=1)
        a = rng.uniform(-0.5, 0.5, (len(r), 1, 1))                        # position across the band
        b = rng.normal(0.0, 0.5, (len(r), 1, 1))                          # position through it
        lock_w = (1.0 + width_jitter * (2.0 * np.random.default_rng(seed + 7).random(len(guides)) - 1.0))[own]
        w = width * lock_w[:, None, None] * (1.0 - taper * t)
        band = across[own] * (a * w) + radial[own] * (b * thickness)
        root_blend = np.clip(1.0 - t / 0.12, 0.0, 1.0)
        off = (r - g_roots[own])[:, None, :]
        strand = guides[own] + off * root_blend + band * (1.0 - root_blend)
        fz = frizz * (1.0 + 2.0 * (rng.random((len(r), 1, 1)) < escape))
        strand = strand + np.cumsum(rng.normal(size=strand.shape), axis=1) * fz * t / np.sqrt(steps)
        if fray:
            # ends fan out: each hair drifts its own way over the last third
            way = rng.normal(size=(len(r), 1, 3))
            way /= np.linalg.norm(way, axis=2, keepdims=True)
            strand = strand + way * fray * np.clip((t - 0.65) / 0.35, 0.0, 1.0) ** 2
        if shorten:
            # hairs end at different lengths so a lock tapers to wisps instead of a blunt cut;
            # each strand is resampled along its own path up to its length fraction
            keep = 1.0 - shorten * rng.random(len(r))
            tt = np.linspace(0.0, 1.0, steps)
            src = tt[None, :] * keep[:, None] * (steps - 1)
            k0 = np.floor(src).astype(int); k1 = np.minimum(k0 + 1, steps - 1); f = (src - k0)[..., None]
            rows = np.arange(len(r))[:, None]
            strand = strand[rows, k0] * (1 - f) + strand[rows, k1] * f
        out[lo:lo + 4096] = strand
    flat = out.reshape(-1, 3)
    q, n = scalp.nearest(flat)
    depth = np.einsum("ij,ij->i", flat - q, n)
    under = depth < 0.0008
    flat[under] = q[under] + n[under] * 0.0008
    return flat.reshape(out.shape)


def curls(scene, base_verts, style=curly_mop, guides=320, children=50000, steps=48, mat=None, parent=None,
          radius=0.00007, seed=0, grow_args=None, child_args=None, ribbon=None):
    """ribbon: None for round ringlets, or a dict for flat ribbon locks (see
    interpolate_ribbons: width, thickness, taper)."""
    """A head of curls in one call. Returns (object, timings)."""
    import time
    started = time.time()
    scalp = Scalp(base_verts)
    g_roots, _ = sample_roots(scalp, guides, style, seed=seed)
    g, across, radial = grow_ringlets(scalp, g_roots, style, steps=steps, seed=seed, return_frame=True,
                                      **(grow_args or {}))
    t_guides = time.time() - started
    c_roots, _ = sample_roots(scalp, children, style, seed=seed + 1)
    if ribbon is not None:
        kids = interpolate_ribbons(scalp, g, across, radial, c_roots, seed=seed + 2, **ribbon)
    else:
        kids = interpolate_ringlets(scalp, g, c_roots, seed=seed + 2, **(child_args or {}))
    obj = build(scene, "Curls", kids, np.zeros(len(kids)), mat or material(), radius=radius, parent=parent)
    return obj, {"guides": len(g), "children": len(kids), "guide_seconds": round(t_guides, 1),
                 "total_seconds": round(time.time() - started, 1)}
